// Build canonical WF-60 input payload for Slack-outbound logging.
// Chained after Post to Slack — uses the Slack API response ts for slack_message_ts.
// WF-51 caller may optionally pass userId/consultationId; WF-60 falls back to slack_channel_id lookup.
const triggerInput = $('Execute Workflow Trigger').first().json;
const slackResp = $input.first().json;

const channelId = triggerInput.channelId || slackResp.channel || null;
const slackMessageTs = slackResp.ts || (slackResp.message && slackResp.message.ts) || null;
const messageText = triggerInput.messageText || (slackResp.message && slackResp.message.text) || null;

return [{
  json: {
    transport: 'slack',
    direction: 'outbound',
    messageType: 'slack_text',
    content: messageText,
    slackChannelId: channelId,
    slackMessageTs: slackMessageTs,
    userId: triggerInput.userId || null,
    consultationId: triggerInput.consultationId || null,
    whatsappMessageId: null,
    phoneNumber: null,
    metadata: {
      transport: 'slack',
      slackChannelId: channelId,
      slackMessageTs: slackMessageTs,
      slackApiOk: slackResp.ok != null ? slackResp.ok : null,
      timestamp: new Date().toISOString()
    }
  }
}];

const input = $input.first().json;
const channelId = input.channelId;
const messageText = input.messageText;

if (!channelId || !/^[CDG][A-Z0-9]{8,}$/.test(channelId)) {
  throw new Error('WF-51 contract violation: channelId missing or invalid (must match ^[CDG][A-Z0-9]{8,}$). Got: ' + JSON.stringify(channelId));
}
if (!messageText || typeof messageText !== 'string' || messageText.trim() === '') {
  throw new Error('WF-51 contract violation: messageText missing or empty.');
}

return [{ json: input }];

